(function() {
    'use strict';

    class NearshoreAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'NearShore: Reshoring & Supply Chain Geopolitics';
            this.version = '1.1.0';
            this._dsSnaps = []; // domainState snapshots per completed period, for correct Undo

            this.ROUNDS = [
                {
                    title: 'Round 1: Supply Chain Assessment',
                    brief: 'Assess current supply chain vulnerabilities and invest in intelligence gathering. Apex sources 65% from Asia. Decide whether to invest in tariff risk analysis, supplier diversification, scenario planning, Mexico due diligence, China auditing, and policy intelligence.',
                    decisions: [
                        { key: 'd1', label: 'Tariff Risk Assessment', options: [
                            { value: 0, text: 'Ignore tariff risks' },
                            { value: 1, text: 'Use industry reports only' },
                            { value: 2, text: 'Full vulnerability mapping ($2M)' }
                        ]},
                        { key: 'd2', label: 'Supplier Diversification', options: [
                            { value: 0, text: 'Maintain status quo' },
                            { value: 1, text: 'Identify 3-5 alternates ($4M)' }
                        ]},
                        { key: 'd3', label: 'Scenario Planning', options: [
                            { value: 0, text: 'Single best-case forecast' },
                            { value: 1, text: 'Build 3-scenario model ($1.2M)' }
                        ]},
                        { key: 'd4', label: 'Mexico Site Visit', options: [
                            { value: 0, text: 'Rely on broker reports' },
                            { value: 1, text: 'Send assessment team ($850K)' }
                        ]},
                        { key: 'd5', label: 'China Supply Chain Audit', options: [
                            { value: 0, text: 'Third-party audit ($200K)' },
                            { value: 1, text: 'Full internal audit ($3.2M)' }
                        ]},
                        { key: 'd6', label: 'Political Intelligence', options: [
                            { value: 0, text: 'Monitor public information' },
                            { value: 1, text: 'Hire policy consultant ($800K/yr)' }
                        ]}
                    ]
                },
                {
                    title: 'Round 2: Mexico Nearshoring Evaluation',
                    brief: 'Evaluate specific Mexico locations and make capital investment decisions. Choose between Monterrey (mature workforce, higher cost) and Guadalajara (lower cost, longer ramp-up). Define entry mode, product mix, workforce strategy, and ESG standards.',
                    decisions: [
                        { key: 'd1', label: 'Mexico Manufacturing Site', options: [
                            { value: 0, text: 'Delay site selection' },
                            { value: 1, text: 'Monterrey ($185M CAPEX)' },
                            { value: 2, text: 'Guadalajara ($165M CAPEX)' }
                        ]},
                        { key: 'd2', label: 'Entry Mode', options: [
                            { value: 0, text: 'Contract manufacturing partnership' },
                            { value: 1, text: 'Greenfield plant (24 months)' },
                            { value: 2, text: 'Acquire existing facility ($220M)' }
                        ]},
                        { key: 'd3', label: 'Product Mix for Mexico', options: [
                            { value: 0, text: 'Commodity bearings and fasteners' },
                            { value: 1, text: 'High-precision hydraulic systems' },
                            { value: 2, text: 'Mixed product portfolio' }
                        ]},
                        { key: 'd4', label: 'Workforce Development', options: [
                            { value: 0, text: 'Recruit from competitor facilities' },
                            { value: 1, text: 'Partner with vocational schools ($8M)' },
                            { value: 2, text: 'Import key managers from Houston' }
                        ]},
                        { key: 'd5', label: 'Supply Chain Localization', options: [
                            { value: 0, text: 'Import suppliers from U.S. and Asia' },
                            { value: 1, text: 'Develop local Mexican suppliers ($12M)' }
                        ]},
                        { key: 'd6', label: 'ESG Standards', options: [
                            { value: 0, text: 'Minimum Mexican compliance' },
                            { value: 1, text: 'Best-in-class environmental ($6M)' }
                        ]}
                    ]
                },
                {
                    title: 'Round 3: Crisis Response',
                    brief: 'BREAKING: The U.S. president announces 35% tariffs on all Chinese imports, effective in 60 days. This directly affects 42% of Apex sourcing. How do you respond to protect operations, margins, and customer relationships?',
                    decisions: [
                        { key: 'd1', label: 'Tariff Response Strategy', options: [
                            { value: 0, text: 'Absorb tariff cost in margin' },
                            { value: 1, text: 'Accelerate shift to Mexico and domestic' },
                            { value: 2, text: 'Negotiate customer price increases' },
                            { value: 3, text: 'Mixed strategy across segments' }
                        ]},
                        { key: 'd2', label: 'Supplier Acceleration', options: [
                            { value: 0, text: 'Gradual transition' },
                            { value: 1, text: 'Emergency premium suppliers (+15%)' },
                            { value: 2, text: 'Expedite Mexico facility ramp-up' }
                        ]},
                        { key: 'd3', label: 'Customer Communication', options: [
                            { value: 0, text: 'Wait for customers to ask' },
                            { value: 1, text: 'Proactive outreach to top 20 customers' },
                            { value: 2, text: 'Highlight Mexico nearshoring capability' },
                            { value: 3, text: 'Offer rebates for lead-time flexibility' }
                        ]},
                        { key: 'd4', label: 'Inventory Risk Management', options: [
                            { value: 0, text: 'Minimize inventory to reduce exposure' },
                            { value: 1, text: 'Build safety stock before tariffs ($78M)' },
                            { value: 2, text: 'Use supplier consignment agreements' }
                        ]},
                        { key: 'd5', label: 'Financial Hedging', options: [
                            { value: 0, text: 'Remain unhedged' },
                            { value: 1, text: 'Implement currency and commodity hedges' }
                        ]},
                        { key: 'd6', label: 'Organizational Response', options: [
                            { value: 0, text: 'Maintain normal rhythms' },
                            { value: 1, text: 'Activate crisis management team' }
                        ]}
                    ]
                },
                {
                    title: 'Round 4: Dual-Sourcing Strategy',
                    brief: 'Optimize your supply chain portfolio across multiple geographies and customer segments. Design the geographic mix, supplier relationship depth, technology investments, integration level, and sustainability strategy.',
                    decisions: [
                        { key: 'd1', label: 'Geographic Sourcing Mix', options: [
                            { value: 0, text: 'Asia-dominant (40% MX / 50% Asia / 10% US)' },
                            { value: 1, text: 'Balanced (50% MX / 40% Asia / 10% US)' },
                            { value: 2, text: 'Mexico-heavy (65% MX / 30% Asia / 5% US)' }
                        ]},
                        { key: 'd2', label: 'Supplier Relationships', options: [
                            { value: 0, text: 'Competitive dynamic (4-5 per category)' },
                            { value: 1, text: 'Single-source partnerships (2-3 strategic)' }
                        ]},
                        { key: 'd3', label: 'Visibility Investment', options: [
                            { value: 0, text: 'Minimal technology investment' },
                            { value: 1, text: 'Enhanced demand forecasting ($8M)' },
                            { value: 2, text: 'Full IoT and real-time tracking ($22M)' }
                        ]},
                        { key: 'd4', label: 'Vertical Integration', options: [
                            { value: 0, text: 'Remain pure contract manufacturer' },
                            { value: 1, text: 'Backward integrate ($80-150M)' },
                            { value: 2, text: 'Forward integrate into OEM assembly' }
                        ]},
                        { key: 'd5', label: 'Strategic Partnership', options: [
                            { value: 0, text: 'Remain independent' },
                            { value: 1, text: 'Joint venture with Mexican partner ($120M)' },
                            { value: 2, text: 'Acquire Mexican competitor ($180M)' }
                        ]},
                        { key: 'd6', label: 'Sustainability Target', options: [
                            { value: 0, text: 'No specific target' },
                            { value: 1, text: 'Carbon neutral by 2035' },
                            { value: 2, text: 'Carbon neutral by 2030 ($35M)' }
                        ]}
                    ]
                },
                {
                    title: 'Round 5: Long-Term Architecture',
                    brief: 'Design the supply chain architecture for the next 5-10 years. Balance cost, resilience, and growth by defining regional footprint, digitalization, supplier ecosystem, inventory policy, resilience metrics, and organizational capability.',
                    decisions: [
                        { key: 'd1', label: 'Long-Term Regional Footprint', options: [
                            { value: 0, text: 'Asia-dominant (50% Asia / 30% MX / 20% US)' },
                            { value: 1, text: 'Balanced triad (40% MX / 35% Asia / 25% US)' },
                            { value: 2, text: 'Mexico-dominant (60% MX / 25% Asia / 15% US)' }
                        ]},
                        { key: 'd2', label: 'Digitalization Roadmap', options: [
                            { value: 0, text: 'Legacy systems with incremental fixes' },
                            { value: 1, text: 'Moderate digital upgrade ($18M)' },
                            { value: 2, text: 'Full Industry 4.0 with AI and IoT ($45M)' }
                        ]},
                        { key: 'd3', label: 'Supplier Ecosystem', options: [
                            { value: 0, text: 'Traditional purchasing' },
                            { value: 1, text: 'Supplier consolidation (reduce 30%)' },
                            { value: 2, text: 'Invest in capacity building ($20M)' }
                        ]},
                        { key: 'd4', label: 'Inventory Policy', options: [
                            { value: 0, text: 'Just-in-time with 95th percentile safety' },
                            { value: 1, text: 'Strategic buffer (10% quarterly demand)' },
                            { value: 2, text: 'Consignment agreements with suppliers' }
                        ]},
                        { key: 'd5', label: 'Resilience Metrics', options: [
                            { value: 0, text: 'Continue qualitative assessments' },
                            { value: 1, text: 'Formal resilience scorecard' },
                            { value: 2, text: 'Integrated ERM framework' }
                        ]},
                        { key: 'd6', label: 'Organizational Capability', options: [
                            { value: 0, text: 'Outsource to consultant' },
                            { value: 1, text: 'Embed expertise in supply chain team' },
                            { value: 2, text: 'Hire Chief Resilience Officer ($350K/yr)' }
                        ]}
                    ]
                }
            ];

            this.EVENTS = [
                [
                    { prob: 0.40, name: 'Industry Validation', desc: 'A trade association report shows 62% of auto OEMs are actively reducing China exposure. Customer pressure on Apex intensifies.', costMod: 0, riskMod: -0.02, delivMod: 0, flexMod: -0.02 },
                    { prob: 0.30, name: 'Vietnam Disruption', desc: 'A pandemic-like outbreak in Vietnam creates 4-week manufacturing disruption. Lead times extend from 45 to 75 days.', costMod: 2.5, riskMod: -0.04, delivMod: -0.03, flexMod: -0.03 },
                    { prob: 0.20, name: 'Mexico Inflation Spike', desc: 'Mexican inflation rises to 8.5%, driving wage increases. Mexico nearshoring labor cost advantage narrows.', costMod: 1.5, riskMod: 0, delivMod: 0, flexMod: 0 },
                    { prob: 0.10, name: 'China Export Controls', desc: 'China announces export controls on critical minerals used in bearings. Emergency sourcing at 35% premium required for 12% of BOM.', costMod: 4.0, riskMod: -0.06, delivMod: -0.04, flexMod: -0.05 }
                ],
                [
                    { prob: 0.35, name: 'Competitor in Monterrey', desc: 'A major competitor announces a new plant in Monterrey with a secured VW contract. Wage inflation in Monterrey accelerates.', costMod: 1.0, riskMod: 0, delivMod: 0, flexMod: -0.01 },
                    { prob: 0.30, name: 'Mexico Tax Holiday', desc: 'Mexican government announces a 5-year tax holiday for advanced manufacturing. Mexico ROI improves by approximately 120 basis points.', costMod: -2.0, riskMod: 0.02, delivMod: 0, flexMod: 0.01 },
                    { prob: 0.25, name: 'PE Sale-Leaseback Offer', desc: 'A private equity firm offers to acquire and leaseback the Houston HQ facility, freeing $320M in capital.', costMod: 0, riskMod: 0, delivMod: 0, flexMod: 0.03 },
                    { prob: 0.10, name: 'Peso Devaluation', desc: 'A geopolitical crisis triggers 15% peso devaluation. Mexico unit costs drop 12%, but currency risk increases.', costMod: -3.0, riskMod: -0.02, delivMod: 0, flexMod: 0.02 }
                ],
                [
                    { prob: 0.45, name: 'Tariff Threat Withdrawn', desc: 'U.S. negotiating team reaches a deal with China within 40 days. Tariff threat is withdrawn. Teams that over-invested in acceleration face sunk costs.', costMod: -1.0, riskMod: 0.03, delivMod: 0.01, flexMod: 0.02 },
                    { prob: 0.30, name: 'Tariffs Implemented', desc: 'Tariffs are implemented as announced. VW and Airbus launch new supplier qualification favoring nearshored suppliers.', costMod: 5.0, riskMod: -0.06, delivMod: -0.04, flexMod: -0.04 },
                    { prob: 0.15, name: 'Vietnam Port Strikes', desc: 'Vietnam experiences port strikes and labor protests. Lead times extend 30% across all Asian sources.', costMod: 2.0, riskMod: -0.03, delivMod: -0.03, flexMod: -0.02 },
                    { prob: 0.10, name: 'Customer Volume Cut', desc: 'A major customer (GM) announces vertical integration and reduces supplier volume by 25%.', costMod: 1.5, riskMod: -0.02, delivMod: -0.02, flexMod: -0.03 }
                ],
                [
                    { prob: 0.40, name: 'Competitor Automation', desc: 'A new competitor announces a nearshoring-first strategy with significantly lower Mexico costs through automation.', costMod: 1.5, riskMod: -0.01, delivMod: 0, flexMod: -0.02 },
                    { prob: 0.30, name: 'Mexico Wage Demand', desc: 'Mexico labor union demands 18% wage increase effective next year. Mexico cost advantage narrows 40-50%.', costMod: 3.0, riskMod: -0.01, delivMod: 0, flexMod: -0.01 },
                    { prob: 0.20, name: 'Buy American Provisions', desc: 'New U.S. federal procurement rules restrict contracts to USMCA-qualified components. Opens 15% of aerospace demand.', costMod: -1.0, riskMod: 0.02, delivMod: 0.01, flexMod: 0.02 },
                    { prob: 0.10, name: 'Asia IP Breach', desc: 'A data breach at a major Asia supplier exposes customer IP designs. Accelerates customer demand for nearshoring.', costMod: 0.5, riskMod: -0.03, delivMod: 0, flexMod: -0.01 }
                ],
                [
                    { prob: 0.35, name: 'Global Recession', desc: 'A global recession materializes. Customer demand falls 22% across the board. Over-capacity becomes acute.', costMod: 4.0, riskMod: -0.04, delivMod: -0.02, flexMod: -0.03 },
                    { prob: 0.30, name: 'Automation Revolution', desc: 'Automation costs drop dramatically. Location becomes less important than automation levels. Competitive advantage shifts.', costMod: -2.0, riskMod: 0.01, delivMod: 0.02, flexMod: 0.03 },
                    { prob: 0.25, name: 'Activist Investor', desc: 'An activist investor campaign criticizes environmental footprint. ESG-heavy funds pressure for accelerated decarbonization.', costMod: 1.0, riskMod: -0.02, delivMod: 0, flexMod: 0 },
                    { prob: 0.10, name: 'Mexico Innovation Hub', desc: 'Mexico emerges as a world-class manufacturing hub with a significant tech innovation ecosystem. Early investors gain ecosystem benefits.', costMod: -3.0, riskMod: 0.04, delivMod: 0.02, flexMod: 0.04 }
                ]
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    capital: 280,
                    capitalSpent: 0,
                    revenue: 3200,
                    costIndex: 100,
                    riskScore: 0.65,
                    deliveryScore: 0.913,
                    flexScore: 0.72,
                    chinaShare: 42,
                    vietnamShare: 23,
                    mexicoShare: 8,
                    domesticShare: 22,
                    otherShare: 5,
                    r1TariffAssess: 0,
                    r1SupplierDiv: 0,
                    r1Scenario: 0,
                    r1MexicoVisit: 0,
                    r1ChinaAudit: 0,
                    r1PoliticalIntel: 0,
                    r2Site: 0,
                    costHistory: [],
                    riskHistory: [],
                    deliveryHistory: [],
                    flexHistory: [],
                    capitalHistory: [],
                    eventLog: []
                };
                this._dsSnaps = [JSON.parse(JSON.stringify(state.domainState))]; // snap 0 = initial
            } else {
                // Undo path: the framework pops history and re-invokes initialize().
                // Restore domainState to the snapshot matching the (now shorter) history
                // so metrics/charts stay in sync with the period counter.
                var h = (state.history || []).length;
                if (this._dsSnaps.length > h + 1 && this._dsSnaps[h]) {
                    var snap = JSON.parse(JSON.stringify(this._dsSnaps[h]));
                    var ds = state.domainState;
                    for (var k in ds) { if (!(k in snap)) delete ds[k]; }
                    for (var k2 in snap) { ds[k2] = snap[k2]; }
                    this._dsSnaps = this._dsSnaps.slice(0, h + 1);
                }
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    d1: 0, d2: 0, d3: 0, d4: 0, d5: 0, d6: 0
                };
            }
            this._updateBriefing(state);
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.textContent = round.title;

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.textContent = round.brief;

            var container = document.getElementById('decisionsContainer');
            if (!container) return;
            container.innerHTML = '';

            for (var i = 0; i < round.decisions.length; i++) {
                var dec = round.decisions[i];
                var group = document.createElement('div');
                group.className = 'nearshore-sim-decision-group';

                var lbl = document.createElement('label');
                lbl.setAttribute('for', 'input_' + dec.key);
                lbl.textContent = (i + 1) + '. ' + dec.label;
                group.appendChild(lbl);

                var sel = document.createElement('select');
                sel.id = 'input_' + dec.key;
                sel.setAttribute('data-key', dec.key);
                for (var j = 0; j < dec.options.length; j++) {
                    var opt = document.createElement('option');
                    opt.value = dec.options[j].value;
                    opt.textContent = dec.options[j].text;
                    sel.appendChild(opt);
                }
                group.appendChild(sel);
                container.appendChild(group);
            }
        }

        _selectEvent(roundIdx) {
            var events = this.EVENTS[roundIdx];
            var r = Math.random();
            var cumulative = 0;
            for (var i = 0; i < events.length; i++) {
                cumulative += events[i].prob;
                if (r <= cumulative) return events[i];
            }
            return events[events.length - 1];
        }

        validateDecisions(decisions) {
            // NOTE: do NOT rebuild the decision form here. Rebuilding resets every
            // <select> to its first option, so the player's choices would be wiped
            // before they are read. Simply read the current selections.
            var idx = Math.min((window.mySimulation.state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            for (var i = 0; i < round.decisions.length; i++) {
                var dec = round.decisions[i];
                var el = document.getElementById('input_' + dec.key);
                if (el) {
                    var parsed = parseInt(el.value, 10);
                    decisions[dec.key] = isNaN(parsed) ? 0 : parsed;
                }
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var roundIdx = Math.min(period - 1, 4);

            var costDelta = 0;
            var riskDelta = 0;
            var delivDelta = 0;
            var flexDelta = 0;
            var capSpent = 0;

            if (roundIdx === 0) {
                if (d.d1 === 2) { capSpent += 2; costDelta -= 0.3; riskDelta += 0.03; }
                else if (d.d1 === 1) { riskDelta += 0.01; }
                if (d.d2 === 1) { capSpent += 4; flexDelta += 0.04; riskDelta += 0.02; }
                if (d.d3 === 1) { capSpent += 1.2; riskDelta += 0.02; flexDelta += 0.02; }
                if (d.d4 === 1) { capSpent += 0.85; costDelta -= 0.5; }
                if (d.d5 === 1) { capSpent += 3.2; riskDelta += 0.03; delivDelta += 0.01; }
                else { capSpent += 0.2; riskDelta += 0.01; }
                if (d.d6 === 1) { capSpent += 0.8; riskDelta += 0.02; }
                ds.r1TariffAssess = d.d1;
                ds.r1SupplierDiv = d.d2;
                ds.r1Scenario = d.d3;
                ds.r1MexicoVisit = d.d4;
                ds.r1ChinaAudit = d.d5;
                ds.r1PoliticalIntel = d.d6;
            }
            else if (roundIdx === 1) {
                if (d.d1 === 1) {
                    capSpent += 185; costDelta -= 3.0; delivDelta += 0.015;
                    ds.chinaShare -= 12; ds.mexicoShare += 12;
                } else if (d.d1 === 2) {
                    capSpent += 165; costDelta -= 2.5; delivDelta += 0.012;
                    ds.chinaShare -= 10; ds.mexicoShare += 10;
                }
                ds.r2Site = d.d1;
                if (d.d2 === 1) { costDelta -= 0.5; flexDelta += 0.03; }
                else if (d.d2 === 2) { capSpent += 35; costDelta -= 1.5; delivDelta += 0.01; }
                if (d.d3 === 1) { costDelta += 0.5; riskDelta += 0.01; }
                else if (d.d3 === 2) { costDelta -= 0.5; delivDelta += 0.008; flexDelta += 0.02; }
                if (d.d4 === 1) { capSpent += 8; riskDelta += 0.02; delivDelta += 0.01; }
                else if (d.d4 === 2) { costDelta += 0.3; }
                if (d.d5 === 1) { capSpent += 12; costDelta -= 1.0; flexDelta += 0.03; riskDelta += 0.02; }
                if (d.d6 === 1) { capSpent += 6; riskDelta += 0.02; }
                if (ds.r1MexicoVisit === 1 && d.d1 > 0) {
                    costDelta -= 0.8; riskDelta += 0.01;
                }
            }
            else if (roundIdx === 2) {
                if (d.d1 === 0) { costDelta += 4.0; riskDelta -= 0.04; }
                else if (d.d1 === 1) { capSpent += 25; costDelta -= 1.0; riskDelta += 0.05; flexDelta += 0.04; ds.chinaShare -= 8; ds.mexicoShare += 5; ds.domesticShare += 3; }
                else if (d.d1 === 2) { costDelta += 1.5; delivDelta -= 0.01; }
                else if (d.d1 === 3) { capSpent += 12; costDelta += 1.0; riskDelta += 0.03; flexDelta += 0.02; ds.chinaShare -= 5; ds.mexicoShare += 3; ds.domesticShare += 2; }
                if (d.d2 === 1) { capSpent += 15; costDelta += 1.5; delivDelta += 0.015; }
                else if (d.d2 === 2) { capSpent += 10; costDelta -= 0.5; delivDelta += 0.01; }
                if (d.d3 === 1) { riskDelta += 0.03; delivDelta += 0.01; }
                else if (d.d3 === 2 && ds.r2Site > 0) { riskDelta += 0.04; flexDelta += 0.02; }
                else if (d.d3 === 3) { capSpent += 8; delivDelta += 0.005; }
                if (d.d4 === 1) { capSpent += 78; delivDelta += 0.02; flexDelta += 0.03; costDelta += 0.5; }
                else if (d.d4 === 2) { flexDelta += 0.02; }
                if (d.d5 === 1) { capSpent += 2; riskDelta += 0.02; }
                if (d.d6 === 1) { riskDelta += 0.02; delivDelta += 0.01; flexDelta += 0.01; }
                if (ds.r1TariffAssess === 2) { riskDelta += 0.02; costDelta -= 0.5; }
                if (ds.r1Scenario === 1) { flexDelta += 0.02; }
                if (ds.r1PoliticalIntel === 1) { riskDelta += 0.01; }
            }
            else if (roundIdx === 3) {
                if (d.d1 === 0) { costDelta += 1.0; riskDelta -= 0.03; }
                else if (d.d1 === 1) { costDelta -= 1.5; riskDelta += 0.04; delivDelta += 0.01; ds.chinaShare -= 5; ds.mexicoShare += 3; ds.domesticShare += 2; }
                else if (d.d1 === 2) { costDelta -= 3.0; riskDelta += 0.06; delivDelta += 0.015; flexDelta += 0.03; ds.chinaShare -= 12; ds.mexicoShare += 10; ds.domesticShare += 2; }
                if (d.d2 === 0) { flexDelta += 0.03; }
                else if (d.d2 === 1) { riskDelta -= 0.01; flexDelta -= 0.02; }
                if (d.d3 === 0) { costDelta += 0.3; }
                else if (d.d3 === 1) { capSpent += 8; riskDelta += 0.02; delivDelta += 0.01; }
                else if (d.d3 === 2) { capSpent += 22; riskDelta += 0.04; delivDelta += 0.02; flexDelta += 0.03; }
                if (d.d4 === 0) { flexDelta += 0.01; }
                else if (d.d4 === 1) { capSpent += 115; costDelta -= 2.0; riskDelta += 0.02; }
                else if (d.d4 === 2) { capSpent += 30; delivDelta += 0.01; }
                if (d.d5 === 0) { flexDelta += 0.02; }
                else if (d.d5 === 1) { capSpent += 120; riskDelta += 0.03; flexDelta += 0.02; costDelta -= 1.5; }
                else if (d.d5 === 2) { capSpent += 180; riskDelta += 0.04; flexDelta += 0.03; costDelta -= 2.5; }
                if (d.d6 === 1) { riskDelta += 0.01; }
                else if (d.d6 === 2) { capSpent += 35; riskDelta += 0.03; delivDelta += 0.005; }
            }
            else if (roundIdx === 4) {
                if (d.d1 === 0) { costDelta += 1.0; riskDelta -= 0.02; }
                else if (d.d1 === 1) { costDelta -= 1.5; riskDelta += 0.04; delivDelta += 0.01; flexDelta += 0.03; ds.chinaShare -= 5; ds.mexicoShare += 5; }
                else if (d.d1 === 2) { costDelta -= 2.5; riskDelta += 0.06; delivDelta += 0.015; flexDelta += 0.05; ds.chinaShare -= 10; ds.mexicoShare += 8; ds.domesticShare += 2; }
                if (d.d2 === 1) { capSpent += 18; riskDelta += 0.02; delivDelta += 0.01; }
                else if (d.d2 === 2) { capSpent += 45; riskDelta += 0.04; delivDelta += 0.02; flexDelta += 0.03; }
                if (d.d3 === 1) { riskDelta -= 0.01; flexDelta -= 0.01; }
                else if (d.d3 === 2) { capSpent += 20; riskDelta += 0.03; flexDelta += 0.02; delivDelta += 0.01; }
                if (d.d4 === 0) { delivDelta += 0.01; flexDelta -= 0.01; }
                else if (d.d4 === 1) { delivDelta += 0.005; flexDelta += 0.02; costDelta += 0.5; }
                else if (d.d4 === 2) { flexDelta += 0.01; }
                if (d.d5 === 1) { riskDelta += 0.03; flexDelta += 0.02; }
                else if (d.d5 === 2) { riskDelta += 0.05; flexDelta += 0.03; delivDelta += 0.01; }
                if (d.d6 === 0) { riskDelta += 0.01; }
                else if (d.d6 === 1) { riskDelta += 0.02; flexDelta += 0.01; }
                else if (d.d6 === 2) { capSpent += 0.35; riskDelta += 0.04; flexDelta += 0.02; delivDelta += 0.005; }
            }

            var evt = this._selectEvent(roundIdx);
            costDelta += evt.costMod;
            riskDelta += evt.riskMod;
            delivDelta += evt.delivMod;
            flexDelta += evt.flexMod;

            ds.costIndex = Math.max(70, Math.min(130, ds.costIndex + costDelta));
            ds.riskScore = Math.max(0.30, Math.min(1.0, ds.riskScore + riskDelta));
            ds.deliveryScore = Math.max(0.70, Math.min(1.0, ds.deliveryScore + delivDelta));
            ds.flexScore = Math.max(0.40, Math.min(1.0, ds.flexScore + flexDelta));
            ds.capitalSpent += capSpent;
            ds.capital = Math.max(0, 280 - ds.capitalSpent);

            ds.chinaShare = Math.max(0, Math.min(100, ds.chinaShare));
            ds.vietnamShare = Math.max(0, Math.min(100, ds.vietnamShare));
            ds.mexicoShare = Math.max(0, Math.min(100, ds.mexicoShare));
            ds.domesticShare = Math.max(0, Math.min(100, ds.domesticShare));

            var total = ds.chinaShare + ds.vietnamShare + ds.mexicoShare + ds.domesticShare + ds.otherShare;
            if (total !== 100) {
                var adj = 100 - total;
                ds.otherShare = Math.max(0, ds.otherShare + adj);
            }

            ds.costHistory.push(Math.round(ds.costIndex * 10) / 10);
            ds.riskHistory.push(Math.round(ds.riskScore * 100) / 100);
            ds.deliveryHistory.push(Math.round(ds.deliveryScore * 1000) / 1000);
            ds.flexHistory.push(Math.round(ds.flexScore * 100) / 100);
            ds.capitalHistory.push(Math.round(capSpent * 10) / 10);
            ds.eventLog.push(evt.name);

            // snapshot end-of-period domainState for correct Undo (index = period number)
            this._dsSnaps[period] = JSON.parse(JSON.stringify(ds));

            var eventPanel = document.getElementById('eventPanel');
            var eventText = document.getElementById('eventText');
            if (eventPanel && eventText) {
                eventPanel.style.display = 'block';
                eventText.innerHTML = '<strong>' + evt.name + ':</strong> ' + evt.desc;
            }

            // Render the next round's briefing/decision form synchronously (deterministic;
            // avoids the previous 500ms timer that could leave the old form on screen).
            if (state.currentPeriod < this.ROUNDS.length) {
                this._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }

            return {
                period: period,
                costIndex: ds.costIndex,
                riskScore: ds.riskScore,
                deliveryScore: ds.deliveryScore,
                flexScore: ds.flexScore,
                capitalSpent: capSpent,
                event: evt.name,
                chinaShare: ds.chinaShare,
                mexicoShare: ds.mexicoShare,
                capital: ds.capital
            };
        }

