        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var r = last.results || {};

            var costIdx = r.costIndex || 100;
            var riskSc = r.riskScore || 0.65;
            var delivSc = r.deliveryScore || 0.913;
            var flexSc = r.flexScore || 0.72;

            var costPoints = 0;
            if (costIdx <= 100) costPoints = 30;
            else if (costIdx <= 105) costPoints = 20;
            else if (costIdx <= 115) costPoints = 10;

            var riskPoints = 0;
            if (riskSc >= 0.85) riskPoints = 30;
            else if (riskSc >= 0.78) riskPoints = 20;
            else if (riskSc >= 0.70) riskPoints = 10;

            var delivPoints = 0;
            if (delivSc >= 0.92) delivPoints = 20;
            else if (delivSc >= 0.88) delivPoints = 14;
            else if (delivSc >= 0.82) delivPoints = 8;

            var flexPoints = 0;
            if (flexSc >= 0.90) flexPoints = 20;
            else if (flexSc >= 0.85) flexPoints = 14;
            else if (flexSc >= 0.80) flexPoints = 8;

            var totalScore = costPoints + riskPoints + delivPoints + flexPoints;
            var performance = 'Concerning';
            if (totalScore >= 85) performance = 'Excellent';
            else if (totalScore >= 70) performance = 'Proficient';
            else if (totalScore >= 55) performance = 'Developing';

            var insights = [];
            if (costIdx > 105) insights.push('Cost index exceeded target. Review sourcing mix for cost reduction opportunities.');
            if (riskSc < 0.78) insights.push('Resilience below target. Increase geographic diversification and supplier development.');
            if (delivSc < 0.88) insights.push('Delivery reliability needs improvement. Consider buffer inventory and closer supplier relationships.');
            if (flexSc < 0.80) insights.push('Strategic flexibility is low. Invest in visibility, alternative suppliers, and organizational resilience.');
            if (totalScore >= 85) insights.push('Outstanding supply chain transformation. You balanced cost discipline with strategic resilience.');

            return {
                totalScore: totalScore,
                costIndex: costIdx,
                riskScore: riskSc,
                deliveryScore: delivSc,
                flexScore: flexSc,
                performance: performance,
                insights: insights
            };
        }

